text:
.appearance-options {
  display: flex;
  flex-direction: row;
  gap: 15px;
  margin-block-start: 9px;

  & .radio-icon {
    -moz-context-properties: fill, stroke;
    fill: var(--color-text-base);
    stroke: var(--color-text-secondary);
    margin-inline-start: -22px;
    background-color: var(--color-surface-base);
    border-radius: 6px;
  }

  & radio {
    display: flex;
    align-items: end;
    background-color: var(--color-surface-subtle);
    border: 1px solid var(--color-surface-border);
    border-radius: 10px;
    padding: 3px;
    margin: 0;

    & .radio-check {
      margin-block: 0;
    }

    & .radio-label-box {
      display: flex;
      flex-direction: column;
      gap: 3px;
      margin: 0;
      padding: 0;
    }

    & .radio-label {
      align-self: start;
      margin: 0;
      padding: 0;
      line-height: 1.3;
    }

    &:hover {
      background-color: var(--color-surface-border);
    }

    &[selected] {
      border-color: var(--selected-item-color);
      outline: 1px solid var(--selected-item-color);

      .radio-icon {
        fill: var(--selected-item-color);
        stroke: var(--selected-item-color);
      }
    }
  }
}

#defaultFlagThreaded .radio-icon {
  list-style-image: var(--threaded-illustration);
}

#defaultFlagUnthreaded .radio-icon {
  list-style-image: var(--unthreaded-illustration);
}

#defaultFlagGrouped .radio-icon {
  list-style-image: var(--grouped-illustration);
}

#appearanceStyleTable .radio-icon {
  list-style-image: var(--table-view-illustration);
}

#appearanceStyleCards .radio-icon {
  list-style-image: var(--cards-view-illustration);
}
